 pg.goto('http://127.0.0.1:8001/v3/?day=180');pg.wait_for_function('window.PlannerCore')
 pg.evaluate('''async()=>{const C=PlannerCore;await C.load();await C.settings({babyName:'QA',birthday:'2026-01-01',startDay:180,stage:'middle',mealsPerDay:2});for(const [id,slot,type,memo] of [['one',1,'meal','첫 메모'],['two',2,'meal','둘 메모'],['snack',4,'snack','간식 메모']])await C.saveMeal(180,id,{slot,type,memo,foods:[{name:'당근',g:20}],actualIntake:10},[], '날짜 메모 보존');}''')
 pg.reload();pg.locator('[data-view=month]').click();pg.locator('.month-day[data-day="180"]').click();assert pg.locator('[data-view=month]').get_attribute('aria-pressed')=='true';assert 'selected' in pg.locator('.month-day[data-day="180"]').get_attribute('class');assert pg.locator('[data-meal=one]').count();print('PASS monthly selection stays monthly and displays selected meals')
 for mid,note in [('one','첫 수정'),('two','둘 수정'),('snack','간식 수정')]:
  pg.locator('[data-meal='+mid+']').click();pg.locator('#dayMemo').fill(note);pg.locator('#saveSheet').click();pg.wait_for_function('!document.querySelector("#sheet").open')
 pg.reload();d=pg.evaluate('PlannerCore.snapshot().days[180]');assert d['memo']=='날짜 메모 보존';assert [m['memo'] for m in d['meals']]==['첫 수정','둘 수정','간식 수정'];print('PASS independent meal/snack memos persisted, daily memo preserved')
 pg.locator('[data-meal=one]').click();pg.locator('[data-meal-type]').select_option('commercial');pg.locator('[data-product-name]').fill('테스트 제품');pg.locator('[data-product-grams]').fill('80');pg.locator('[data-product-ingredients]').fill('소고기, 애호박, 비트, 미등록');pg.locator('#saveSheet').click();pg.wait_for_function('!document.querySelector("#sheet").open');src=pg.locator('[data-meal=one] img').evaluate_all('(es)=>es.map(e=>e.src)');assert all(any('/'+n+'.svg' in s for s in src) for n in ['beef','zucchini','beet','default']),src
 assert pg.locator('[data-meal=snack] .meal-number').inner_text()=='간식';assert '이미지 저장' in pg.locator('[data-action=export]').inner_text();assert not pg.locator('[data-action=export-day]').is_visible();print('PASS product CSV SVGs and default, snack label, distinct image actions')
 assert pg.locator('#legacyLink').get_attribute('aria-checked')=='false';pg.locator('#legacyLink').click();pg.wait_for_url('**/?day=180');assert pg.locator('#v3Switch').get_attribute('aria-checked')=='true';assert pg.locator('[data-edit-meal=one]').count();pg.evaluate('''()=>{window.editOpenCount=0;const open=window.openSharedMeals;window.openSharedMeals=(...a)=>{editOpenCount++;return open(...a)}}''');pg.locator('[data-edit-meal=one]').click();assert pg.evaluate('editOpenCount')==1;assert pg.locator('#sharedMemo').input_value()=='첫 수정';assert pg.locator('#sharedSlot').input_value()=='1';assert pg.locator('.mobile-edit-route').count();pg.locator('#sharedMemo').fill('V1 수정');pg.locator('#sharedMealDialog [type=submit]').click();pg.wait_for_function('!document.querySelector("#sharedMealDialog").open');pg.evaluate('openSharedMeals(180)');pg.wait_for_selector('#sharedMealDialog .meal-add-actions');buttons=pg.locator('#sharedMealDialog .meal-add-actions').first.locator('button');a=buttons.nth(0).bounding_box();c=buttons.nth(1).bounding_box();assert a['x']+a['width']<c['x'] or a['y']+a['height']<c['y'];pg.locator('#sharedMealDialog header [data-close]').click();pg.locator('#v3Switch').click();pg.wait_for_url('**/v3/?day=180');assert pg.evaluate('PlannerCore.snapshot().days[180].meals[0].memo')=='V1 수정';print('PASS V1 direct edit, button gap, shared memo/date and OFF toggles')
 result=pg.evaluate('''async()=>{const C=PlannerCore;const before=C.snapshot();await C.applyTemplate({stage:'middle',count:2,startDay:180,length:1,offset:1,mode:'replace'});const after=C.snapshot();if(after.days[180].memo!==before.days[180].memo)throw Error('daily memo');for(const m of before.days[180].meals){const a=after.days[180].meals.find(x=>x.id===m.id);if(!a||a.memo!==m.memo||a.actualIntake!==m.actualIntake)throw Error('meal preservation')}if(JSON.stringify(after.ingredients)!==JSON.stringify(before.ingredients))throw Error('ingredients');return 'PASS explicit template replacement preserves intake, IDs, memos and ingredient records'}''');print(result)
 pg.locator('#moreButton').click();pg.locator('[data-action=example]').click();assert pg.locator('.template-guides h3').count()==5;pg.locator('#closeSheet').click() if pg.locator('#closeSheet').count() else pg.evaluate('document.querySelector("#sheet").close()')
 assert not errors,errors
 # Missing optional icon module must not interrupt either app.
 for route in ['/','/v3/']:
  c=b.new_context();page=c.new_page();page.route('**/v3/icons.js',lambda r:r.abort());page.route('**/assets/food-icons/adapter.js',lambda r:r.abort());es=[];page.on('pageerror',lambda e:es.append(str(e)));page.goto('http://127.0.0.1:8001'+route);page.wait_for_timeout(300);assert not es,es;c.close()
 print('PASS missing icon module resilience');b.close()
